public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        // 两半必须各自递归排序后再合并（此前漏掉分治，直接 merge 两个乱序序列）
        ListNode mid = getMid(head);
        ListNode second = mid.next;
        mid.next = null;
        ListNode newHead = sortList(head);
        second = sortList(second);
        return mergeList(newHead, second);
    }

    private ListNode mergeList(ListNode head, ListNode second) {
        ListNode newHead = new ListNode();
        ListNode p1 = head, p2 = second, p = newHead;
        // 只把 p 指向较小节点、p 前移，不断任何链（断链会拆碎链表并让 p 变 null 触发 NPE）
        while (p1 != null && p2 != null) {
            if (p1.val < p2.val) {
                p.next = p1;
                p1 = p1.next;
            } else {
                p.next = p2;
                p2 = p2.next;
            }
            p = p.next;
        }
        if (p1 != null) p.next = p1;
        if (p2 != null) p.next = p2;
        return newHead.next;
    }

    private ListNode getMid(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        // fast 每轮完整走 2 步、slow 走 1 步，fast 到尾时 slow 恰在中点
        // 条件 fast.next.next != null 保证「slow 前进 ⇔ fast 走满 2 步」（此前偶数长度 slow 多走，[1,2] 返回节点 2 致无限递归）
        ListNode fast = head, slow = head;
        while (fast.next != null && fast.next.next != null) {
            fast = fast.next.next;
            slow = slow.next;
        }
        return slow;
    }

public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        int len = getLen(head);
        ListNode dummy = new ListNode(0, head);
        for (int i = 1; i <= len; i <<= 1) {
            ListNode pre = dummy, cur = dummy.next;
            while (cur != null) {
                ListNode head1 = cur;
                for (int j = 1; j < i && cur.next != null; j++) {
                    cur = cur.next;
                }
                ListNode head2 = cur.next;
                cur.next = null;
                cur = head2;
                for (int j = 1; j < i && cur != null && cur.next != null; j++) {
                    cur = cur.next;
                }
                ListNode next = null;
                if (cur != null) {
                    next = cur.next;
                    cur.next = null;
                }
                pre.next = merge(head1, head2);
                while (pre.next != null) {
                    pre = pre.next;
                }
                cur = next;
            }
        }
        return dummy.next;
    }

    private int getLen(ListNode head) {
        int count = 0;
        ListNode p = head;
        while (p != null) {
            count++;
            p = p.next;
        }
        return count;
    }

    private ListNode merge(ListNode head1, ListNode head2) {
        ListNode dummy = new ListNode();
        ListNode p1=  head1, p2 = head2, p = dummy;
        while (p1 != null && p2 != null) {
            if (p1.val < p2.val) {
                p.next = p1;
                p1 = p1.next;
            } else {
                p.next = p2;
                p2 = p2.next;
            }
            p = p.next;
        }
        if (p1 != null) {
            p.next = p1;
        }
        if (p2 != null) {
            p.next = p2;
        }
        return dummy.next;
    }

